/*
 * The default style family of ViteHub UI: ui-sdk's own stylesheet, the shadcn tokens of `tokens.css` mapped onto its
 * `--ui-*` variables, the ViteHub look, the rules for the kit's TagsInput, and the CSS-only parts that ui-sdk does not
 * have (skeleton, empty state, badge, chip, alert, card, and avatar group). The build
 * replaces the web.css import with the file itself, with the workspace patch (`patches/@ui-sdk__core@*.patch`).
 *
 *   @import "@vite-hub/kit/styles/tokens.css";
 *   @import "@vite-hub/kit/styles/default.css";
 *
 * Load it only in apps without Nuxt UI. web.css styles plain `a`, `kbd`, and `button`, shares `data-slot` names with
 * Nuxt UI, and reads `--ui-radius` as the whole radius where Nuxt UI reads it as the base step, so the two restyle each
 * other.
 */

@import "@ui-sdk/core/web.css";

/* On `.dark` and `[data-theme="dark"]` too, so a dark subtree reads its own tokens and not the page's. */
:root,
.dark,
[data-theme="dark"] {
  --ui-background: var(--background);
  --ui-foreground: var(--foreground);
  --ui-muted: var(--muted);
  --ui-muted-foreground: var(--muted-foreground);
  --ui-border: var(--border);
  --ui-input: var(--input);
  --ui-primary: var(--primary);
  --ui-primary-foreground: var(--primary-foreground);
  --ui-destructive: var(--destructive);
  /* The ViteHub focus: a 2px ring in `--ring`, 2px outside the part. Text fields turn their own frame blue instead. */
  --ui-ring: var(--ring);
  --ui-ring-border: var(--ring);
  --ui-ring-width: 2px;
  --ui-ring-offset: 2px;
  --ui-overlay: var(--overlay);
  /* `--radius` is the base step: 6px controls, 12px menus, popovers, and dialogs. */
  --ui-radius: calc(var(--radius) * 1.5);
  --ui-radius-popup: calc(var(--radius) * 3);
  --ui-font-size: 0.875rem;
  --ui-font-sans: var(--font-sans);
  --ui-font-mono: var(--font-mono);
}

/* web.css has no page base. It has no specificity, so any app rule wins. */
:where(html) {
  background: var(--background);
  color: var(--foreground);
  font-family: var(--font-sans);
}

@layer ui-sdk {
  /* Timeline and Waterfall: web.css has no rules for them yet. */
  [data-slot="timeline"] {
    display: flex;
    flex-direction: column;
    margin: 0;
    padding: 0;
    color: var(--ui-foreground);
    font-size: var(--ui-font-size);
    list-style: none;

    &[data-orientation="horizontal"] {
      display: grid;
      grid-template-columns: repeat(var(--timeline-count, 1), minmax(0, 1fr));
    }

    &[data-busy] {
      opacity: 0.6;
    }
  }

  /* The marker sits in its own column, and the connector runs down that column to the next marker. */
  [data-slot="timeline-item"] {
    position: relative;
    display: grid;
    grid-template-columns: calc(var(--ui-spacing) * 2) minmax(0, 1fr);
    align-items: baseline;
    column-gap: calc(var(--ui-spacing) * 3);
    padding-block-end: calc(var(--ui-spacing) * 5);

    &:is([data-last], :last-child) {
      padding-block-end: 0;
    }

    & > :not([data-slot="timeline-marker"], [data-slot="timeline-connector"]) {
      grid-column: 2;
    }

    &[data-orientation="horizontal"] {
      grid-template-columns: minmax(0, 1fr);
      padding: calc(var(--ui-spacing) * 5) calc(var(--ui-spacing) * 4) 0 0;

      & > :not([data-slot="timeline-marker"], [data-slot="timeline-connector"]) {
        grid-column: 1;
      }
    }
  }

  [data-slot="timeline-marker"] {
    grid-row: 1;
    grid-column: 1;
    align-self: center;
    width: calc(var(--ui-spacing) * 2);
    height: calc(var(--ui-spacing) * 2);
    border: 1px solid var(--ui-input);
    border-radius: 50%;
    background: var(--ui-background);

    [data-slot="timeline-item"][data-first] > & {
      border-color: var(--ui-primary);
      background: var(--ui-primary);
    }

    &[data-orientation="horizontal"] {
      position: absolute;
      inset-block-start: var(--ui-spacing);
      inset-inline-start: 0;
    }
  }

  [data-slot="timeline-connector"] {
    position: absolute;
    inset-block: calc(var(--ui-spacing) * 4.5) calc(var(--ui-spacing) * 0.5);
    inset-inline-start: calc(var(--ui-spacing) - 0.5px);
    width: 1px;
    background: var(--ui-border);

    [data-slot="timeline-item"]:is([data-last], :last-child) > & {
      display: none;
    }

    &[data-orientation="horizontal"] {
      inset-block: calc(var(--ui-spacing) * 2 - 0.5px) auto;
      inset-inline: calc(var(--ui-spacing) * 3) var(--ui-spacing);
      width: auto;
      height: 1px;
    }
  }

  [data-slot="timeline-title"] {
    font-weight: 500;
  }

  :is([data-slot="timeline-time"], [data-slot="timeline-description"]) {
    color: var(--ui-muted-foreground);
    font-size: calc(var(--ui-font-size) - 0.0625rem);
  }

  [data-slot="timeline-time"] {
    font-variant-numeric: tabular-nums;
  }

  /* Rows share the columns of the grid through subgrid, so a row can take a hover fill and a focus ring. */
  [data-slot="waterfall"] {
    display: grid;
    grid-template-columns: minmax(6rem, max-content) max-content minmax(12rem, 1fr);
    width: 100%;
    overflow: hidden;
    border: 1px solid var(--ui-border);
    border-radius: var(--ui-radius-popup, calc(var(--ui-radius) * 1.5));
    background: var(--ui-background);
    color: var(--ui-foreground);
    font-size: calc(var(--ui-font-size) - 0.0625rem);
  }

  :is([data-slot="waterfall-header-row"], [data-slot="waterfall-row"]) {
    display: grid;
    grid-column: 1 / -1;
    grid-template-columns: subgrid;
    align-items: center;
    min-height: calc(var(--ui-spacing) * 8);
  }

  [data-slot="waterfall-header-row"] {
    border-block-end: 1px solid var(--ui-border);
    color: var(--ui-muted-foreground);
  }

  [data-slot="waterfall-row"] {
    &:is(:hover, [data-selected]) {
      background: var(--ui-muted);
    }

    &:focus-visible {
      outline-offset: calc(var(--ui-ring-width, 4px) * -1);
    }
  }

  :is(
    [data-slot="waterfall-column-header"],
    [data-slot="waterfall-row-header"],
    [data-slot="waterfall-cell"]
  ) {
    min-width: 0;
    padding-inline: calc(var(--ui-spacing) * 3);
    overflow: hidden;
    font-weight: 400;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  [data-slot="waterfall-row-header"] {
    padding-inline-start: calc(var(--ui-spacing) * 3 + (var(--waterfall-level, 1) - 1) * var(--ui-spacing) * 4);
  }

  [data-slot="waterfall-cell"] {
    color: var(--ui-muted-foreground);
    font-variant-numeric: tabular-nums;
    text-align: end;
  }

  /* The axis header and the bars have the same box, so a tick and a bar at the same time line up. */
  [data-slot="waterfall-column-header"]:has([data-slot="waterfall-axis"]) {
    position: relative;
    align-self: stretch;
    margin-inline-end: calc(var(--ui-spacing) * 3);
    padding: 0;
  }

  [data-slot="waterfall-axis"] {
    position: absolute;
    inset: 0;
    container-type: inline-size;
  }

  /* On a narrow axis, every other tick keeps its line and drops its label, so the labels do not overlap. */
  @container (max-width: 24rem) {
    [data-slot="waterfall-tick"]:nth-child(even) {
      color: transparent;
    }
  }

  [data-slot="waterfall-tick"] {
    position: absolute;
    inset-block: 0;
    inset-inline-start: var(--waterfall-tick);
    display: flex;
    align-items: center;
    padding-inline-start: var(--ui-spacing);
    border-inline-start: 1px solid var(--ui-border);
    font-size: calc(var(--ui-font-size) - 0.125rem);
    font-variant-numeric: tabular-nums;
  }

  [data-slot="waterfall-mark"] {
    position: absolute;
    inset-block-end: 0;
    inset-inline-start: var(--waterfall-mark);
    width: 1px;
    height: calc(var(--ui-spacing) * 2);
    overflow: hidden;
    background: var(--ui-destructive);
    color: transparent;
  }

  [data-slot="waterfall-bar"] {
    position: relative;
    align-self: stretch;
    margin-inline-end: calc(var(--ui-spacing) * 3);

    &::before {
      position: absolute;
      inset-block: calc(50% - var(--ui-spacing));
      inset-inline-start: var(--waterfall-start);
      width: max(2px, var(--waterfall-size));
      border-radius: max(0px, calc(var(--ui-radius) - 2px));
      background: var(--ui-primary);
      content: "";
    }
  }

  /* A text field turns its own frame blue on focus: the border and a 1px shadow, with no ring outside. */
  :is(
    [data-slot="input"],
    [data-slot="textarea"],
    [data-slot="combobox-input"],
    [data-slot="autocomplete-input"],
    [data-slot="trigger-menu-input"],
    [data-slot="select-trigger"],
    [data-slot="date-picker-input"],
    [data-slot="otp-input-slot"],
    [data-slot="color-picker-input"],
    [data-slot="color-picker-channel-input"],
    [data-slot="token-input-editor"],
    [data-slot="number-input-control"]
  ):not([data-slot="input-group"] > *):focus-visible,
  :is(
    [data-slot="date-input"],
    [data-slot="time-input"],
    [data-slot="password-input"],
    [data-slot="input-group"],
    [data-slot="tags-input"]
  ):has(:focus-visible) {
    border-color: var(--ring);
    box-shadow: 0 0 0 1px var(--ring);
    outline: none;
  }

  /* The input group draws the frame, so its input has none, and web.css's ring around the group goes. */
  [data-slot="input-group"]:has(> [data-slot="input"]:focus-visible) {
    outline: none;
  }

  /* An open select keeps its border; only focus turns it blue. */
  [data-slot="select-trigger"][data-open]:not(:focus-visible) {
    border-color: var(--ui-input);
  }

  /* A 1px line under the active tab. */
  [data-slot="tabs-tab"] {
    border-bottom-width: 1px;
  }

  /* Items in a list that clips its overflow keep the ring inside. */
  :is(
    [data-slot="tabs-tab"],
    [data-slot="accordion-trigger"],
    [data-slot="segmented-control-item"],
    [data-slot="calendar-day"],
    [data-slot="scroll-area-viewport"],
    [data-slot="navigation-menu-content"] [data-slot="navigation-menu-link"]
  ):focus-visible {
    outline-offset: calc(var(--ui-ring-width) * -1);
  }

  /* Popups float on a 1px ring and a soft shadow, with no border. `--popover` is translucent over a blurred page. */
  :is(
    [data-slot="menu-content"],
    [data-slot="select-content"],
    [data-slot="combobox-content"],
    [data-slot="autocomplete-content"],
    [data-slot="trigger-menu-content"],
    [data-slot="popover-content"],
    [data-slot="hover-card-content"],
    [data-slot="navigation-menu-viewport"],
    [data-slot="date-picker-content"]
  ) {
    border-width: 0;
    background: var(--popover);
    backdrop-filter: blur(12px);
    box-shadow: var(--shadow-popover);
    color: var(--popover-foreground);
  }

  :is([data-slot="dialog-content"], [data-slot="alert-dialog-content"]) {
    border-width: 0;
    box-shadow: var(--shadow-dialog);
  }

  [data-slot="toast"] {
    border-width: 0;
    box-shadow: var(--shadow-popover);
  }

  [data-slot="command-item-icon"] {
    color: var(--ui-muted-foreground);
  }

  /* The selected tree row shows its fill only, in the normal weight. */
  [data-slot="tree-label"]:is([data-selected], [data-current]) {
    font-weight: inherit;
  }

  /* A toggle icon marked `data-variant="fill"`, such as a star, fills while the toggle is pressed. */
  [data-slot="toggle"][data-pressed] [data-slot="toggle-icon"][data-variant="fill"] svg {
    fill: currentColor;
  }

  /* Cards are 8px. */
  [data-slot="waterfall"] {
    border-radius: calc(var(--radius) * 2);
  }

  /* An icon-only close button in a dialog or a drawer sits in the top end corner, as in shadcn. */
  :is([data-slot="dialog-content"], [data-slot="alert-dialog-content"], [data-slot="drawer-content"])
    > :is([data-slot="dialog-close"], [data-slot="alert-dialog-close"], [data-slot="drawer-close"])[aria-label]:has(> svg:only-child) {
    position: absolute;
    inset-block-start: calc(var(--ui-spacing) * 3);
    inset-inline-end: calc(var(--ui-spacing) * 3);
    width: calc(var(--ui-spacing) * 7);
    height: calc(var(--ui-spacing) * 7);
    border-color: transparent;
    background: transparent;
    color: var(--ui-muted-foreground);

    &:hover {
      background: var(--ui-muted);
      color: var(--ui-foreground);
    }
  }

  /*
   * The Nuxt UI looks that the ui-sdk set of `@vite-hub/ui` (`uiSdkComponents`) asks for: `soft`, `ghost`, and `link`
   * buttons, the `xs` and `sm` sizes, a spinner, a dialog footer, a menu item description, and a tab badge.
   */
  [data-slot="button"] {
    &:is([data-variant="soft"], [data-variant="ghost"], [data-variant="link"]) {
      border-color: transparent;
    }

    &[data-variant="soft"] {
      background: var(--ui-muted);

      &:hover:not([data-disabled]) {
        background: color-mix(in oklab, var(--ui-muted), var(--ui-foreground) 8%);
      }
    }

    &:is([data-variant="ghost"], [data-variant="link"]) {
      background: transparent;
    }

    &[data-variant="link"] {
      height: auto;
      padding-inline: 0;
      color: var(--ui-muted-foreground);

      &:hover:not([data-disabled]) {
        background: transparent;
        color: var(--ui-foreground);
      }
    }

    &[data-size="xs"] {
      gap: calc(var(--ui-spacing) * 1);
      height: calc(var(--ui-spacing) * 6);
      padding-inline: calc(var(--ui-spacing) * 2);
      font-size: 0.75rem;
    }

    &[data-size="sm"] {
      height: calc(var(--ui-spacing) * 7);
      padding-inline: calc(var(--ui-spacing) * 2.5);
    }

    &[aria-label]:has(> svg:only-child, > [data-slot$="-icon"]:only-child) {
      &[data-size="xs"] {
        width: calc(var(--ui-spacing) * 6);
      }

      &[data-size="sm"] {
        width: calc(var(--ui-spacing) * 7);
      }
    }
  }

  [data-slot="spinner"] {
    animation: kit-spin 1s linear infinite;
  }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="spinner"] {
      animation-duration: 3s;
    }
  }

  @keyframes kit-spin {
    to {
      rotate: 1turn;
    }
  }

  [data-slot="dialog-footer"] {
    display: flex;
    justify-content: flex-end;
    gap: calc(var(--ui-spacing) * 2);
  }

  :is([data-slot="menu-item-description"], [data-slot="tabs-tab-badge"]) {
    color: var(--ui-muted-foreground);
    font-size: 0.75rem;
  }

  [data-slot="menu-item-description"] {
    display: block;
  }

  [data-slot="tags-input"] {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: calc(var(--ui-spacing) * 1);
    width: 100%;
    min-height: calc(var(--ui-spacing) * 8);
    padding: calc(var(--ui-spacing) * 1) calc(var(--ui-spacing) * 1.5);
    border: 1px solid var(--ui-input);
    border-radius: var(--ui-radius);
    background: var(--ui-background);
    color: var(--ui-foreground);
    font-size: var(--ui-font-size);

    &:has(:focus-visible) {
      border-color: var(--ui-ring-border);
      outline: var(--ui-ring-width, 4px) solid var(--ui-ring);
    }

    &[data-invalid] {
      border-color: var(--ui-destructive);
    }

    &[data-disabled] {
      opacity: 0.5;
      cursor: not-allowed;
    }
  }

  [data-slot="tags-input-item"] {
    display: inline-flex;
    align-items: center;
    gap: calc(var(--ui-spacing) * 1);
    height: calc(var(--ui-spacing) * 5.5);
    padding-inline: calc(var(--ui-spacing) * 1.5) 2px;
    border: 1px solid var(--ui-input);
    border-radius: calc(var(--ui-radius) / 2);
    background: var(--ui-muted);
    font-size: calc(var(--ui-font-size) - 0.0625rem);
    white-space: nowrap;

    &[data-highlighted] {
      border-color: var(--ui-foreground);
    }
  }

  :is([data-slot="tags-input-item-delete"], [data-slot="tags-input-clear"]) {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 1rem;
    height: 1rem;
    padding: 0;
    border: 0;
    background: none;
    color: var(--ui-muted-foreground);
    font: inherit;
    cursor: pointer;

    &:hover {
      color: var(--ui-foreground);
    }

    &[data-disabled] {
      display: none;
    }
  }

  [data-slot="tags-input-input"] {
    flex: 1;
    min-width: 6rem;
    height: calc(var(--ui-spacing) * 5.5);
    padding: 0 calc(var(--ui-spacing) * 1);
    border: 0;
    background: transparent;
    color: inherit;
    font: inherit;

    &:focus-visible {
      outline: none;
    }

    &::placeholder {
      color: var(--ui-muted-foreground);
    }
  }

  /*
   * The CSS-only parts: plain HTML with a `vh-` slot name, which neither Nuxt UI nor web.css uses. They look like the
   * Nuxt UI parts that the Console shows with `@vite-hub/ui/theme.css` today. Their state and sizes are attributes:
   * `data-tone`, `data-size`, and `data-variant`. The rules are in the `ui-sdk` layer, so a utility class wins over them.
   */

  /* A gray block in the place of content that loads. Set its size with the page's own classes. */
  [data-slot="vh-skeleton"] {
    display: block;
    border-radius: calc(var(--radius) * 1.5);
    background: var(--muted);
    animation: vh-skeleton-pulse 2s cubic-bezier(0.4, 0, 0.6, 1) infinite;
  }

  /* A page or a panel with nothing to show: an icon, a title, a description, and actions, centered. */
  [data-slot="vh-empty"] {
    position: relative;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: calc(var(--ui-spacing) * 2);
    min-width: 0;
    padding: calc(var(--ui-spacing) * 5);
    border-radius: calc(var(--radius) * 2);

    @media (width >= 40rem) {
      padding: calc(var(--ui-spacing) * 6);
    }

    @media (width >= 64rem) {
      padding: calc(var(--ui-spacing) * 8);
    }

    &[data-variant="outline"] {
      background: var(--background);
      box-shadow: 0 0 0 1px var(--border);
    }

    & > * {
      max-width: 24rem;
    }

    /* Content after the text, such as a code example, sits 12px below it. */
    & > :not([data-slot^="vh-empty-"]) {
      margin-block-start: calc(var(--ui-spacing) * 1);
    }
  }

  [data-slot="vh-empty-icon"] {
    display: inline-flex;
    flex-shrink: 0;
    align-items: center;
    justify-content: center;
    width: calc(var(--ui-spacing) * 10);
    height: calc(var(--ui-spacing) * 10);
    margin-block-end: calc(var(--ui-spacing) * 2);
    border-radius: 9999px;
    background: var(--muted);
    color: var(--muted-foreground);
    font-size: 1.25rem;

    & > svg {
      width: 1em;
      height: 1em;
    }
  }

  [data-slot="vh-empty-title"] {
    margin: 0;
    color: var(--foreground);
    font-size: 1rem;
    font-weight: 500;
    line-height: 1.5rem;
    text-align: center;
    text-wrap: pretty;
  }

  [data-slot="vh-empty-description"] {
    margin: 0;
    color: var(--muted-foreground);
    font-size: 0.875rem;
    line-height: 1.25rem;
    text-align: center;
    text-wrap: balance;
  }

  [data-slot="vh-empty-actions"] {
    display: flex;
    flex-shrink: 0;
    flex-wrap: wrap;
    justify-content: center;
    gap: calc(var(--ui-spacing) * 2);
    margin-block-start: calc(var(--ui-spacing) * 2);
  }

  /* `xs` and `sm` for a panel or a sidebar: a smaller icon and 14px and 12px text. */
  [data-slot="vh-empty"]:is([data-size="xs"], [data-size="sm"]) {
    & [data-slot="vh-empty-title"] {
      font-size: 0.875rem;
      line-height: 1.25rem;
    }

    & [data-slot="vh-empty-description"] {
      font-size: 0.75rem;
      line-height: 1rem;
    }
  }

  [data-slot="vh-empty"][data-size="xs"] [data-slot="vh-empty-icon"] {
    width: calc(var(--ui-spacing) * 8);
    height: calc(var(--ui-spacing) * 8);
    font-size: 1rem;
  }

  [data-slot="vh-empty"][data-size="sm"] [data-slot="vh-empty-icon"] {
    width: calc(var(--ui-spacing) * 9);
    height: calc(var(--ui-spacing) * 9);
    font-size: 1.125rem;
  }

  /*
   * A count or a state in a few words. Neutral by default; `data-tone` gives it a status color: a 10% fill, a 25% ring,
   * and the darker text shade.
   */
  [data-slot="vh-badge"] {
    --vh-badge-fill: var(--muted);
    --vh-badge-ring: var(--ui-border-accented);
    display: inline-flex;
    align-items: center;
    gap: calc(var(--ui-spacing) * 1);
    padding: calc(var(--ui-spacing) * 1) calc(var(--ui-spacing) * 2);
    border-radius: calc(var(--radius) * 1.5);
    background: var(--vh-badge-fill);
    box-shadow: inset 0 0 0 1px var(--vh-badge-ring);
    color: var(--ui-text);
    font-size: 0.75rem;
    font-weight: 500;
    line-height: 1rem;
    white-space: nowrap;

    &[data-size="sm"] {
      padding: calc(var(--ui-spacing) * 0.5) calc(var(--ui-spacing) * 1.5);
      border-radius: var(--radius);
    }
  }

  /* A dot on the corner of an icon, such as a filter that is on. Leave the dot out, or set `hidden`, to hide it. */
  [data-slot="vh-chip"] {
    position: relative;
    display: inline-flex;
    flex-shrink: 0;
    align-items: center;
    justify-content: center;
  }

  [data-slot="vh-chip-indicator"] {
    position: absolute;
    top: 0;
    right: 0;
    width: 7px;
    height: 7px;
    border-radius: 9999px;
    background: var(--foreground);
    box-shadow: 0 0 0 1px var(--background);
    translate: 50% -50%;
  }

  /*
   * A notice in a page or a panel: an icon, then the title, the description, and actions. Neutral by default;
   * `data-tone` colors it. `data-variant="outline"` drops the fill. Actions inside `vh-alert-content` go under the text;
   * actions after it sit at the end of the row, centered.
   */
  [data-slot="vh-alert"] {
    --vh-alert-fill: color-mix(in oklab, var(--muted) 50%, transparent);
    --vh-alert-ring: var(--ui-border-accented);
    position: relative;
    display: flex;
    align-items: flex-start;
    gap: calc(var(--ui-spacing) * 2);
    width: 100%;
    padding: calc(var(--ui-spacing) * 3);
    overflow: hidden;
    border-radius: calc(var(--radius) * 2);
    background: var(--vh-alert-fill);
    box-shadow: inset 0 0 0 1px var(--vh-alert-ring);
    color: var(--foreground);

    &[data-variant="outline"] {
      --vh-alert-fill: transparent;
    }

    &[data-variant="outline"]:is(:not([data-tone]), [data-tone="neutral"]) {
      --vh-alert-fill: var(--background);
      --vh-alert-ring: var(--border);
    }

    &:has(> [data-slot="vh-alert-actions"]) {
      align-items: center;
    }

    & > svg {
      width: 1rem;
      height: 1rem;
      margin-block-start: calc(var(--ui-spacing) * 0.5);
    }
  }

  [data-slot="vh-alert-content"] {
    display: flex;
    flex: 1;
    flex-direction: column;
    min-width: 0;
  }

  [data-slot="vh-alert-title"] {
    margin: 0;
    font-size: 0.8125rem;
    font-weight: 500;
    line-height: 1.5;
  }

  [data-slot="vh-alert-description"] {
    margin: 0;
    font-size: 0.75rem;
    line-height: 1.25rem;
  }

  [data-slot="vh-alert-title"] + [data-slot="vh-alert-description"] {
    margin-block-start: calc(var(--ui-spacing) * 1);
  }

  [data-slot="vh-alert-actions"] {
    display: flex;
    flex-shrink: 0;
    flex-wrap: wrap;
    align-items: center;
    gap: calc(var(--ui-spacing) * 1.5);
  }

  [data-slot="vh-alert-content"] > [data-slot="vh-alert-actions"] {
    align-items: flex-start;
    margin-block-start: calc(var(--ui-spacing) * 2.5);
  }

  /* An icon-only button that dismisses the alert, in the top end corner. */
  [data-slot="vh-alert-close"] {
    display: inline-flex;
    flex-shrink: 0;
    align-items: center;
    justify-content: center;
    padding: 0;
    border: 0;
    border-radius: calc(var(--radius) * 1.5);
    background: none;
    color: var(--muted-foreground);
    cursor: pointer;

    &:hover {
      color: var(--ui-text);
    }

    & > svg {
      opacity: 0.8;
    }
  }

  :is([data-slot="vh-badge"], [data-slot="vh-alert"]) {
    &[data-tone="success"] {
      --vh-tone-fill: var(--ui-success);
      --vh-tone-text: var(--vh-text-success);
    }

    &[data-tone="warning"] {
      --vh-tone-fill: var(--ui-warning);
      --vh-tone-text: var(--vh-text-warning);
    }

    &[data-tone="info"] {
      --vh-tone-fill: var(--ui-info);
      --vh-tone-text: var(--vh-text-info);
    }

    &[data-tone="error"] {
      --vh-tone-fill: var(--ui-error);
      --vh-tone-text: var(--vh-text-error);
    }

    &[data-tone]:not([data-tone="neutral"]) {
      --vh-badge-fill: color-mix(in oklab, var(--vh-tone-fill) 10%, transparent);
      --vh-badge-ring: color-mix(in oklab, var(--vh-tone-fill) 25%, transparent);
      --vh-alert-ring: color-mix(in oklab, var(--vh-tone-fill) 25%, transparent);
      color: var(--vh-tone-text);
    }

    &[data-tone]:not([data-tone="neutral"], [data-variant="outline"]) {
      --vh-alert-fill: color-mix(in oklab, var(--vh-tone-fill) 10%, transparent);
    }
  }

  /* A framed box, such as a row of numbers. */
  [data-slot="vh-card"] {
    padding: calc(var(--ui-spacing) * 4);
    overflow: hidden;
    border-radius: calc(var(--radius) * 2);
    background: var(--background);
    box-shadow: 0 0 0 1px var(--border);
  }

  /*
   * Avatars that overlap in a row, each in a 2px ring of the page color, the first on top. Put ui-sdk `Avatar`s and a
   * `vh-avatar-group-count` in it. Avatars are 24px, or 20px with `data-size="sm"`.
   */
  [data-slot="vh-avatar-group"] {
    --vh-avatar-group-size: calc(var(--ui-spacing) * 6);
    display: flex;
    flex-shrink: 0;
    align-items: center;
    isolation: isolate;

    &[data-size="sm"] {
      --vh-avatar-group-size: calc(var(--ui-spacing) * 5);
    }

    & > * {
      position: relative;
      display: inline-flex;
      border-radius: 9999px;
      box-shadow: 0 0 0 2px var(--background);
    }

    & > * + * {
      margin-inline-start: calc(var(--ui-spacing) * -1.5);
    }

    & > :nth-child(1) { z-index: 5; }
    & > :nth-child(2) { z-index: 4; }
    & > :nth-child(3) { z-index: 3; }
    & > :nth-child(4) { z-index: 2; }
    & > :nth-child(5) { z-index: 1; }

    & [data-slot="avatar"] {
      width: var(--vh-avatar-group-size);
      height: var(--vh-avatar-group-size);
      overflow: visible;
      border-radius: 9999px;
      font-size: 0.75rem;
      line-height: 1rem;

      & svg {
        width: 1em;
        height: 1em;
      }
    }

    & [data-slot="avatar-image"] {
      border-radius: inherit;
    }

    & [data-slot="avatar-fallback"] {
      overflow: hidden;
      text-overflow: ellipsis;
      white-space: nowrap;
    }

    &[data-size="sm"] [data-slot="avatar"] {
      font-size: 0.625rem;
      line-height: 0.9375rem;
    }
  }

  [data-slot="vh-avatar-group-count"] {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: var(--vh-avatar-group-size);
    height: var(--vh-avatar-group-size);
    padding-inline: calc(var(--ui-spacing) * 1.5);
    background: var(--muted);
    color: var(--muted-foreground);
    font-size: 0.75rem;
    font-variant-numeric: tabular-nums;
    font-weight: 500;
    line-height: 1;
  }
}

@keyframes vh-skeleton-pulse {
  50% {
    opacity: 0.5;
  }
}
